def make_anti_sudoku(sudoku):
    # We aim to change at most 9 elements in the sudoku to create an anti-sudoku.
    changes = 0

    # Helper function to check if changing a position to a given number is valid
    def can_change(i, j, num):
        # Check row and column
        for k in range(9):
            if sudoku[i][k] == num or sudoku[k][j] == num:
                return False

        # Check 3x3 block
        block_row_start = (i // 3) * 3
        block_col_start = (j // 3) * 3
        for r in range(3):
            for c in range(3):
                if sudoku[block_row_start + r][block_col_start + c] == num:
                    return False

        return True

    # Iterate over the grid to make necessary changes
    for i in range(9):
        for j in range(9):
            if changes >= 9:
                return sudoku

            # Try to find a number to change to
            for num in range(1, 10):
                num_str = str(num)
                if num_str != sudoku[i][j] and can_change(i, j, num_str):
                    sudoku[i][j] = num_str
                    changes += 1
                    break

    return sudoku

