def solve_anti_sudoku(test_cases):
    def create_anti_sudoku(sudoku):
        # Copy the original sudoku
        anti_sudoku = [list(row) for row in sudoku]

        # Change elements to make the anti-sudoku
        for i in range(9):
            for j in range(9):
                if (i % 3 == 0 and j % 3 == 0) or (i == j):
                    # For each block and main diagonal, ensure at least two equal elements
                    possible_values = {1, 2, 3, 4, 5, 6, 7, 8, 9}
                    possible_values.discard(anti_sudoku[i][j])

                    # Choose a new value that ensures at least two equal elements
                    # Choose the first valid value not equal to the original one
                    new_value = possible_values.pop()

                    # Temporarily set the value to a placeholder
                    anti_sudoku[i][j] = new_value

                    # Ensure at least two equal elements in the row
                    if anti_sudoku[i].count(new_value) < 2:
                        for k in range(9):
                            if k != j and anti_sudoku[i][k] == new_value:
                                anti_sudoku[i][j] = new_value
                                break

                    # Ensure at least two equal elements in the column
                    if [anti_sudoku[k][j] for k in range(9)].count(new_value) < 2:
                        for k in range(9):
                            if k != i and anti_sudoku[k][j] == new_value:
                                anti_sudoku[i][j] = new_value
                                break

        return anti_sudoku

    results = []
    for case in test_cases:
        anti_sudoku = create_anti_sudoku(case)
        results.append("\n".join("".join(map(str, row)) for row in anti_sudoku))

    return "\n\n".join(results)

